macro_rules! Shallow {
    () => {
        # [doc = " Describe how shallow clones are handled when fetching, with variants defining how the *shallow boundary* is handled."] # [doc = ""] # [doc = " The *shallow boundary* is a set of commits whose parents are not present in the repository."] # [derive (Default , Debug , Clone , PartialEq , Eq)] pub enum Shallow { # [doc = " Fetch all changes from the remote without affecting the shallow boundary at all."] # [doc = ""] # [doc = " This also means that repositories that aren't shallow will remain like that."] # [default] NoChange , # [doc = " Receive update to `depth` commits in the history of the refs to fetch (from the viewpoint of the remote),"] # [doc = " with the value of `1` meaning to receive only the commit a ref is pointing to."] # [doc = ""] # [doc = " This may update the shallow boundary to increase or decrease the amount of available history."] DepthAtRemote (std :: num :: NonZeroU32) , # [doc = " Increase the number of commits and thus expand the shallow boundary by `depth` commits as seen from our local"] # [doc = " shallow boundary, with a value of `0` having no effect."] Deepen (u32) , # [doc = " Set the shallow boundary at the `cutoff` time, meaning that there will be no commits beyond that time."] Since { # [doc = " The date beyond which there will be no history."] cutoff : gix_date :: Time , } , # [doc = " Receive all history excluding all commits reachable from `remote_refs`. These can be long or short"] # [doc = " ref names or tag names."] Exclude { # [doc = " The ref names to exclude, short or long. Note that ambiguous short names will cause the remote to abort"] # [doc = " without an error message being transferred (because the protocol does not support it)"] remote_refs : Vec < gix_ref :: PartialName > , # [doc = " If some, this field has the same meaning as [`Shallow::Since`] which can be used in combination"] # [doc = " with excluded references."] since_cutoff : Option < gix_date :: Time > , } , }
    };
}

Shallow!()